const fs=require('fs');
function rep(path,before,after){let s=fs.readFileSync(path,'utf8');if(s.includes(after))return;if(!s.includes(before))throw new Error(`Pattern missing in ${path}`);fs.writeFileSync(path,s.replace(before,after));}
const q="async function processQueueBatch(batch){ for(const message of batch.messages||[]){ const id=message?.body?.certificateId; if(!id){message.ack?.();continue;} try{await processCertificate(id);message.ack?.();}catch(e){await failAnalysis(id,e).catch(()=>{});message.retry?.();} } }";
rep('src/services/certificateFraudDetection.js',q,q+"\nasync function processPendingCertificatesDirect(limit=2,{recognizer}={}){\n  const pending=(await db.select('certificates')).filter(c=>c.evidence_path && !c.fraud_processed_at).sort((a,b)=>String(b.evidence_uploaded_at||'').localeCompare(String(a.evidence_uploaded_at||''))).slice(0,Math.max(1,limit));\n  let processed=0, failed=0; const results=[];\n  for(const cert of pending){\n    try{ const result=await processCertificate(cert.id,{recognizer}); processed++; results.push({id:cert.id,status:'processed',review_status:result.review_status}); }\n    catch(error){ failed++; const message=await failAnalysis(cert.id,error); results.push({id:cert.id,status:'failed',error:message}); }\n  }\n  return {selected:pending.length,processed,failed,results};\n}");
rep('src/services/certificateFraudDetection.js','enqueuePendingCertificates,processQueueBatch,monthlyAuditSelected','enqueuePendingCertificates,processQueueBatch,processPendingCertificatesDirect,monthlyAuditSelected');
const expiry="            if (event.cron === (env.PROOF_EXPIRY_CRON || '0 * * * *')) { const { default: proofExpiry } = await import('../src/services/proofExpiry.js'); console.log('Proof expiry cleanup complete:', JSON.stringify(await proofExpiry.runProofExpiryCleanup())); const { default: fraud } = await import('../src/services/certificateFraudDetection.js'); console.log('Certificate fraud backlog enqueue complete:', JSON.stringify(await fraud.enqueuePendingCertificates(100))); }";
rep('worker/index.mjs',expiry,expiry+"\n            if (event.cron === (env.FRAUD_RECOVERY_CRON || '*/10 * * * *')) { const { default: fraud } = await import('../src/services/certificateFraudDetection.js'); console.log('Certificate fraud direct recovery complete:', JSON.stringify(await fraud.processPendingCertificatesDirect(2))); }");
